const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const p = $('Plan').first().json;
return [{ json: { chat_id: p.cfg.chat_id, text: `🚨 <b>SLA watcher: ${p.due_count} просроченных SLA одновременно</b> (порог ${p.cfg.breaker}).\nИндивидуальные эскалации приостановлены, чтобы не засыпать менеджеров. Проверьте очередь и время на сервере; затем поднимите sla_escalation_breaker или закройте SLA.` } }];

const plan = $('Plan').first().json;
const claimed = new Set($input.all().map((i) => Number(i.json.inbox_id)).filter(Boolean));
const cfg = plan.cfg;
const out = [];
for (const it of plan.items.filter((x) => claimed.has(Number(x.inbox_id)))) {
  const link = `[URL=${cfg.portal_url}/crm/deal/details/${it.deal_id}/]сделке #${it.deal_id}[/URL]`;
  const text = `⏰ Просрочен первый ответ по ${link} (${it.client ?? 'клиент'}): ${it.overdue_min} мин сверх SLA.`;
  const cmd = {
    manager: 'im.notify.system.add?USER_ID=' + it.manager_id + '&MESSAGE=' + encodeURIComponent(text + ' Ответьте клиенту.'),
    sla: `crm.item.update?entityTypeId=${cfg.sla_type}&id=${it.sla_item_id}&fields[stageId]=${encodeURIComponent(cfg.stage_fail)}`,
  };
  if (cfg.rop_user_id && String(cfg.rop_user_id) !== String(it.manager_id)) {
    cmd.rop = 'im.notify.system.add?USER_ID=' + cfg.rop_user_id + '&MESSAGE=' + encodeURIComponent(text + ` Ответственный: ${it.manager_id}.`);
  }
  out.push({ json: { method: 'batch', params: { halt: 0, cmd }, caller_workflow: $workflow.name, caller_execution_id: $execution.id, item: it } });
}
return out;

const sent = $('Build escalations').all();
const res = $input.all();
const ok = [], failed = [];
res.forEach((r, i) => {
  const it = sent[i].json.item;
  const errs = Object.values(r.json.result?.result_error ?? {}).filter((v) => v && !(Array.isArray(v) && !v.length));
  (r.json.ok && !errs.length ? ok : failed).push({ ...it, error: r.json.error_code ?? (errs[0] ? JSON.stringify(errs[0]).slice(0, 200) : null) });
});
return [{ json: { ok, failed } }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// One Telegram message per run for the head of sales, not one per deal.
const plan = $('Plan').first().json, c = $('Collect').first().json, cfg = plan.cfg;
const lines = c.ok.map((i) => `• <a href="${esc(cfg.portal_url)}/crm/deal/details/${i.deal_id}/">#${i.deal_id}</a> ${esc(i.client ?? '')}: менеджер ${i.manager_id}, +${i.overdue_min} мин`);
const rest = plan.due_count - c.ok.length - c.failed.length;
const text = [`⏰ <b>SLA первого ответа нарушен: ${c.ok.length}</b>`, ...lines,
  ...(c.failed.length ? [`⚠️ не удалось эскалировать: ${c.failed.length} (повтор в следующем запуске)`] : []),
  ...(rest > 0 ? [`… ещё ${rest} в очереди (лимит ${cfg.lim} за запуск)`] : [])].join('\n');
return [{ json: { chat_id: cfg.chat_id, text, send: c.ok.length + c.failed.length > 0 } }];

// idle: nothing overdue. dry_run: count and log, send nothing. breaker: too many at once = an incident
// (e.g. a backlog or a clock problem), one rate-limited warning instead of N escalations.
const { cfg, due_count, items } = $json;
const mode = due_count === 0 ? 'idle' : cfg.dry_run ? 'dry_run' : due_count > cfg.breaker ? 'breaker' : 'escalate';
return [{ json: { mode, cfg, due_count, items, planned: mode === 'idle' || mode === 'breaker' ? 0 : items.length } }];
